import hashlib


class BloomFilter:
    def __init__(self, size, hashes, seed=0):
        self._size = size
        self._hashes = hashes
        self._seed = seed
        self._bits = bytearray((size + 7) // 8)    # `size` bits, packed 8 to a byte

    def _positions(self, item):
        for i in range(self._hashes):
            digest = hashlib.sha256(f"{self._seed}:{i}:{item}".encode()).digest()
            yield int.from_bytes(digest[:8], "big") % self._size

    def add(self, item):
        for position in self._positions(item):
            self._bits[position // 8] |= 1 << (position % 8)

    def might_contain(self, item):
        return all(self._bits[position // 8] >> (position % 8) & 1 for position in self._positions(item))
